-- V44: replace category-wide education defaults with task-specific panels.
-- The reference product treats each agent as its own form: chips, selects, text areas and uploads
-- are chosen by the task, not inherited blindly from the navigation category.
UPDATE agents
SET ui_config_json = CASE agent_key
    WHEN 'education-homework-review' THEN '{"enabled":true,"title":"开始批改作业","description":"选择学段和学科，上传作业图片或粘贴答案。","icon":"ri-edit-2-line","submitLabel":"开始批改","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学低年级","小学高年级","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"select","required":true,"options":["语文","数学","英语","物理","化学","其他"]},{"key":"task","label":"批改方式","type":"choice","required":true,"options":["指出错误与原因","给分并给改进建议","只给提示，不直接作答"]},{"key":"content","label":"补充说明","type":"textarea","placeholder":"可选：说明重点关注的题目或评分要求"},{"key":"images","label":"上传作业图片","type":"upload","accept":"image/*","maxFiles":3,"required":true,"helpText":"支持 JPG、PNG，最多 3 张"}]}'
    WHEN 'education-quiz-maker' THEN '{"enabled":true,"title":"生成试题","description":"设置题目范围、难度和输出内容。","icon":"ri-file-list-3-line","submitLabel":"生成试题","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学低年级","小学高年级","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"select","required":true,"options":["语文","数学","英语","物理","化学","生物","历史","地理"]},{"key":"questionType","label":"题型","type":"choice","required":true,"options":["选择题","填空题","简答题","综合题型"]},{"key":"difficulty","label":"难度","type":"select","options":["基础","基础 + 进阶","综合提高"]},{"key":"knowledge","label":"知识点 / 教材范围","type":"textarea","required":true,"placeholder":"例如：初中数学一次函数，八年级上册"}]}'
    WHEN 'education-lesson-planner' THEN '{"enabled":true,"title":"设计教案","description":"确定课题、课时和学生基础，生成可执行的课堂结构。","icon":"ri-book-open-line","submitLabel":"生成教案","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学低年级","小学高年级","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"select","required":true,"options":["语文","数学","英语","物理","化学","生物","历史","地理","美术","音乐"]},{"key":"topic","label":"课题","type":"text","required":true,"placeholder":"例如：八年级物理·浮力"},{"key":"duration","label":"课时","type":"select","options":["20 分钟","40 分钟","45 分钟","90 分钟"]},{"key":"goals","label":"教学目标或学生基础","type":"textarea","placeholder":"补充班级基础、目标和教学限制"}]}'
    WHEN 'education-student-behavior-guide' THEN '{"enabled":true,"title":"分析学生行为","description":"只记录可观察事实，帮助梳理场景、频率和支持方案。","icon":"ri-user-search-line","submitLabel":"开始分析","fields":[{"key":"behaviorType","label":"行为类别","type":"choice","required":true,"options":["注意力分散","言语攻击","肢体冲突","拒绝参与","频繁迟到","作业拖延","情绪波动","社交孤立","顶撞师长","破坏公物"]},{"key":"scene","label":"发生场景","type":"select","required":true,"options":["课堂活动","作业完成","小组合作","家庭沟通","同伴交往","其他"]},{"key":"studentCode","label":"学生代号","type":"text","required":true,"placeholder":"请使用代号，不要填写真实姓名"},{"key":"behavior","label":"具体行为描述","type":"textarea","required":true,"placeholder":"描述发生了什么、频率和持续时间"},{"key":"records","label":"上传观察记录","type":"upload","accept":"image/*","maxFiles":3,"helpText":"可上传脱敏后的图片记录，最多 3 张"}]}'
    WHEN 'education-zhongkao-planner' THEN '{"enabled":true,"title":"制定中考计划","description":"根据地区、剩余时间和学科基础拆解复习节奏。","icon":"ri-calendar-check-line","submitLabel":"生成计划","fields":[{"key":"region","label":"所在地区","type":"text","required":true,"placeholder":"省 / 市即可"},{"key":"days","label":"距离考试天数","type":"number","required":true,"placeholder":"例如 100"},{"key":"subjects","label":"各科基础","type":"textarea","required":true,"placeholder":"说明优势、短板和当前进度"},{"key":"target","label":"目标与限制","type":"textarea","placeholder":"目标分数、作息或课程安排"}]}'
    WHEN 'education-gaokao-choice-advisor' THEN '{"enabled":true,"title":"梳理高考志愿","description":"输入省份、位次和偏好，生成冲稳保调研清单。","icon":"ri-compass-3-line","submitLabel":"生成清单","fields":[{"key":"province","label":"省份","type":"text","required":true,"placeholder":"例如：广东"},{"key":"rank","label":"模考分数 / 位次","type":"text","required":true,"placeholder":"例如：615 分，省排 12000"},{"key":"subjects","label":"选科组合","type":"choice","required":true,"options":["物化生","物化地","史地政","其他"]},{"key":"preferences","label":"专业与地域偏好","type":"textarea","required":true,"placeholder":"说明兴趣、城市、预算等约束"}]}'
    WHEN 'education-postgraduate-planner' THEN '{"enabled":true,"title":"制定考研计划","description":"按目标院校、考试科目和可用时间拆解复习阶段。","icon":"ri-calendar-schedule-line","submitLabel":"生成计划","fields":[{"key":"target","label":"目标院校 / 专业","type":"text","required":true,"placeholder":"例如：某大学教育学"},{"key":"subjects","label":"考试科目","type":"textarea","required":true,"placeholder":"政治、英语、专业课及当前基础"},{"key":"days","label":"每天可投入时间","type":"text","required":true,"placeholder":"例如：工作日 3 小时，周末 6 小时"},{"key":"constraints","label":"跨专业或其他限制","type":"textarea"}]}'
    WHEN 'education-civil-service-essay-coach' THEN '{"enabled":true,"title":"训练公考申论","description":"上传或粘贴题目和材料，按审题、要点和结构逐段反馈。","icon":"ri-file-edit-line","submitLabel":"开始批改","fields":[{"key":"exam","label":"考试类型","type":"choice","required":true,"options":["国考","省考","事业单位","其他"]},{"key":"task","label":"训练任务","type":"select","required":true,"options":["概括归纳","综合分析","提出对策","贯彻执行","大作文"]},{"key":"material","label":"题目 / 材料 / 答案","type":"textarea","required":true,"placeholder":"可直接粘贴文字"},{"key":"attachment","label":"上传材料图片","type":"upload","accept":"image/*","maxFiles":3,"helpText":"图片需清晰可读"}]}'
    WHEN 'education-admission-interview-coach' THEN '{"enabled":true,"title":"模拟升学面试","description":"选择面试类型和目标，开始逐题模拟与反馈。","icon":"ri-mic-line","submitLabel":"开始模拟","fields":[{"key":"type","label":"面试类型","type":"select","required":true,"options":["研究生复试","中学升学","留学申请","奖学金面试","其他"]},{"key":"target","label":"目标院校 / 专业","type":"text","required":true},{"key":"intro","label":"自我介绍或经历","type":"textarea","required":true,"placeholder":"可粘贴已有自我介绍"},{"key":"focus","label":"重点训练","type":"choice","options":["自我介绍","专业问答","经历追问","英语口语"]}]}'
    WHEN 'education-math-tutor' THEN '{"enabled":true,"title":"开始数学辅导","description":"上传题目或粘贴你的解题步骤，智能体会优先给提示。","icon":"ri-function-line","submitLabel":"开始辅导","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"topic","label":"知识点","type":"text","required":true,"placeholder":"例如：二次函数、几何证明"},{"key":"attempt","label":"已尝试步骤","type":"textarea","placeholder":"写出你的思路，便于定位卡点"},{"key":"questionImage","label":"上传题目图片","type":"upload","accept":"image/*","maxFiles":2,"helpText":"支持 JPG、PNG"}]}'
    WHEN 'education-english-grammar-coach' THEN '{"enabled":true,"title":"练习英语语法","description":"选择语法主题，提交例句或练习答案。","icon":"ri-translate-2","submitLabel":"开始练习","fields":[{"key":"level","label":"英语水平","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"grammar","label":"语法主题","type":"choice","required":true,"options":["时态","从句","非谓语","冠词","介词","其他"]},{"key":"content","label":"例句或答案","type":"textarea","required":true,"placeholder":"粘贴需要讲解或批改的内容"}]}'
    WHEN 'education-physics-concept-tutor' THEN '{"enabled":true,"title":"解释物理概念","description":"说明困惑的概念或上传题图，按现象、模型和公式讲解。","icon":"ri-speed-up-line","submitLabel":"开始讲解","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["初中","高中","大学及以上"]},{"key":"concept","label":"概念 / 章节","type":"text","required":true,"placeholder":"例如：动量守恒、失重"},{"key":"question","label":"具体困惑","type":"textarea","required":true},{"key":"image","label":"上传题图","type":"upload","accept":"image/*","maxFiles":2}]}'
    WHEN 'education-chemistry-equation-helper' THEN '{"enabled":true,"title":"检查化学方程式","description":"填写反应物、条件或上传题目，按守恒关系逐步检查。","icon":"ri-flask-line","submitLabel":"开始检查","fields":[{"key":"stage","label":"学习阶段","type":"select","required":true,"options":["初中","高中","大学及以上"]},{"key":"reaction","label":"反应物 / 条件","type":"text","required":true},{"key":"equation","label":"待检查方程式","type":"textarea","required":true},{"key":"image","label":"上传题目图片","type":"upload","accept":"image/*","maxFiles":1}]}'
    WHEN 'education-history-timeline-helper' THEN '{"enabled":true,"title":"整理历史脉络","description":"输入主题和时间范围，生成时间线、背景和影响。","icon":"ri-history-line","submitLabel":"生成时间线","fields":[{"key":"period","label":"历史时期","type":"text","required":true,"placeholder":"例如：工业革命、中国近代史"},{"key":"focus","label":"整理重点","type":"choice","options":["时间线","因果关系","人物事件","复习提纲"]},{"key":"material","label":"已有材料或疑问","type":"textarea"}]}'
    WHEN 'education-geography-map-tutor' THEN '{"enabled":true,"title":"开始地理读图","description":"上传地图、统计图或描述图中信息，按读图步骤分析。","icon":"ri-map-2-line","submitLabel":"开始读图","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"chartType","label":"图表类型","type":"choice","required":true,"options":["地图","等高线图","气候图","统计图","区域图"]},{"key":"question","label":"想解决的问题","type":"textarea","required":true},{"key":"image","label":"上传图表","type":"upload","accept":"image/*","maxFiles":2,"required":true}]}'
    WHEN 'education-reading-comprehension-coach' THEN '{"enabled":true,"title":"批改阅读理解","description":"粘贴文章和题目，或上传清晰图片，答案回到文本证据。","icon":"ri-book-3-line","submitLabel":"开始分析","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"task","label":"题型","type":"choice","required":true,"options":["概括题","作用题","赏析题","主旨题","开放题"]},{"key":"content","label":"文章 / 题目 / 答案","type":"textarea","required":true},{"key":"image","label":"上传试题图片","type":"upload","accept":"image/*","maxFiles":3}]}'
    WHEN 'education-writing-idea-coach' THEN '{"enabled":true,"title":"整理作文思路","description":"确定文体和题目，生成多个立意与结构方向。","icon":"ri-quill-pen-line","submitLabel":"开始构思","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"genre","label":"文体","type":"choice","required":true,"options":["记叙文","议论文","说明文","应用文"]},{"key":"topic","label":"作文题目","type":"text","required":true},{"key":"ideas","label":"已有素材或限制","type":"textarea"}]}'
    WHEN 'education-classroom-activity-designer' THEN '{"enabled":true,"title":"设计课堂活动","description":"填写班级、课题和课时，生成活动步骤与评价点。","icon":"ri-presentation-line","submitLabel":"生成活动","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"text","required":true},{"key":"classSize","label":"班级人数","type":"number","required":true},{"key":"topic","label":"课题与目标","type":"textarea","required":true},{"key":"duration","label":"活动时长","type":"select","options":["10 分钟","20 分钟","40 分钟","一整课时"]}]}'
    WHEN 'education-objective-generator' THEN '{"enabled":true,"title":"生成教学目标","description":"把课题和学生基础转化为可观察、可评价的目标。","icon":"ri-focus-3-line","submitLabel":"生成目标","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"text","required":true},{"key":"topic","label":"课题内容","type":"textarea","required":true},{"key":"baseline","label":"学生基础与限制","type":"textarea"}]}'
    WHEN 'education-course-assessment-helper' THEN '{"enabled":true,"title":"设计课程评价","description":"根据学习目标生成评价任务、成功标准和反馈方式。","icon":"ri-checkbox-circle-line","submitLabel":"生成评价","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"text","required":true},{"key":"objective","label":"学习目标","type":"textarea","required":true},{"key":"format","label":"评价形式","type":"choice","options":["量规","随堂检查","小组展示","项目任务"]}]}'
    WHEN 'education-parent-meeting-speech' THEN '{"enabled":true,"title":"准备家长会发言","description":"围绕会议主题、时长和班级共性问题组织表达。","icon":"ri-chat-quote-line","submitLabel":"生成提纲","fields":[{"key":"stage","label":"年级 / 班级","type":"text","required":true},{"key":"duration","label":"发言时长","type":"select","options":["5 分钟","8 分钟","10 分钟","15 分钟"]},{"key":"topic","label":"会议主题","type":"text","required":true},{"key":"issues","label":"希望沟通的重点","type":"textarea","required":true}]}'
    WHEN 'education-homeroom-helper' THEN '{"enabled":true,"title":"处理班级事务","description":"把班级场景拆成事实、目标、行动和复盘节点。","icon":"ri-team-line","submitLabel":"生成方案","fields":[{"key":"stage","label":"年级 / 班级","type":"text","required":true},{"key":"scene","label":"事务类型","type":"choice","required":true,"options":["主题班会","班级制度","家校沟通","同伴冲突","日常事务"]},{"key":"situation","label":"具体情况","type":"textarea","required":true},{"key":"material","label":"相关记录","type":"upload","accept":"image/*","maxFiles":2}]}'
    WHEN 'education-learning-analysis' THEN '{"enabled":true,"title":"分析班级学情","description":"上传脱敏数据或粘贴统计摘要，归纳共性问题与分层需求。","icon":"ri-bar-chart-2-line","submitLabel":"开始分析","fields":[{"key":"stage","label":"年级 / 班级","type":"text","required":true},{"key":"dataType","label":"数据类型","type":"choice","required":true,"options":["成绩统计","错题统计","课堂观察","作业表现"]},{"key":"summary","label":"数据摘要","type":"textarea","required":true},{"key":"file","label":"上传脱敏表格截图","type":"upload","accept":"image/*","maxFiles":3}]}'
    WHEN 'education-teaching-reflection' THEN '{"enabled":true,"title":"整理教学反思","description":"从目标、课堂证据、意外情况和下一步调整开始复盘。","icon":"ri-refresh-line","submitLabel":"生成反思","fields":[{"key":"subject","label":"学科 / 课题","type":"text","required":true},{"key":"goals","label":"原定目标","type":"textarea","required":true},{"key":"evidence","label":"课堂实际情况","type":"textarea","required":true},{"key":"notes","label":"课堂记录图片","type":"upload","accept":"image/*","maxFiles":2}]}'
    WHEN 'education-home-school-messenger' THEN '{"enabled":true,"title":"撰写家校沟通","description":"基于事实、共同目标和下一步行动组织消息。","icon":"ri-message-2-line","submitLabel":"生成消息","fields":[{"key":"role","label":"你的身份","type":"choice","required":true,"options":["家长","教师","辅导员"]},{"key":"scene","label":"沟通场景","type":"text","required":true},{"key":"goal","label":"希望达成的结果","type":"textarea","required":true},{"key":"tone","label":"语气偏好","type":"select","options":["尊重温和","简洁明确","鼓励支持"]}]}'
    WHEN 'education-parent-child-communication' THEN '{"enabled":true,"title":"梳理亲子沟通","description":"先描述事实和双方需求，再生成可以直接使用的表达句式。","icon":"ri-home-heart-line","submitLabel":"获取建议","fields":[{"key":"stage","label":"孩子学段","type":"select","required":true,"options":["幼儿园","小学","初中","高中","大学及以上"]},{"key":"scene","label":"发生场景","type":"text","required":true},{"key":"concern","label":"具体情况与担心","type":"textarea","required":true},{"key":"goal","label":"希望改变什么","type":"textarea"}]}'
    WHEN 'education-study-habit-coach' THEN '{"enabled":true,"title":"培养学习习惯","description":"选择想改善的习惯，拆成小步行动和记录方式。","icon":"ri-timer-line","submitLabel":"生成计划","fields":[{"key":"stage","label":"年龄 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"habit","label":"想改善的习惯","type":"choice","required":true,"options":["按时作业","专注学习","整理错题","规律作息","自主复习"]},{"key":"schedule","label":"当前作息","type":"textarea","required":true},{"key":"barrier","label":"主要阻碍","type":"textarea"}]}'
    WHEN 'education-child-reading-planner' THEN '{"enabled":true,"title":"制定儿童阅读计划","description":"根据年龄、兴趣和阅读水平安排选书与共读任务。","icon":"ri-book-mark-line","submitLabel":"生成计划","fields":[{"key":"age","label":"年龄 / 年级","type":"text","required":true},{"key":"interest","label":"兴趣主题","type":"text","required":true},{"key":"level","label":"当前阅读水平","type":"select","options":["亲子共读","自主阅读入门","独立阅读","章节书阅读"]},{"key":"time","label":"每周可用时间","type":"text"}]}'
    WHEN 'education-teen-dialogue-helper' THEN '{"enabled":true,"title":"支持青春期沟通","description":"围绕具体场景提供倾听、表达和共同制定规则的方法。","icon":"ri-user-heart-line","submitLabel":"获取建议","fields":[{"key":"stage","label":"学生阶段","type":"select","required":true,"options":["小学高年级","初中","高中","大学及以上"]},{"key":"scene","label":"沟通主题","type":"choice","required":true,"options":["学习成绩","手机使用","同伴关系","情绪变化","作息安排"]},{"key":"situation","label":"发生了什么","type":"textarea","required":true},{"key":"attempted","label":"已经尝试过的方式","type":"textarea"}]}'
    WHEN 'education-science-experiment-guide' THEN '{"enabled":true,"title":"设计科学小实验","description":"优先使用低风险材料，生成问题、步骤、观察记录和安全提示。","icon":"ri-flask-line","submitLabel":"设计实验","fields":[{"key":"age","label":"年龄 / 学段","type":"select","required":true,"options":["幼儿园","小学","初中","高中"]},{"key":"topic","label":"实验主题","type":"text","required":true},{"key":"materials","label":"现有材料","type":"textarea","required":true},{"key":"safety","label":"需要安全提示","type":"checkbox","defaultValue":true}]}'
